<div class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1 class="m-0 text-success font-weight-bold">Kategori Obat</h1></div><div class="col-sm-6 text-right"><form action="proses/proseskategori.php?aksi=tambah" method="POST" class="form-inline float-right"><input type="text" name="namakategori" class="form-control form-control-sm mr-2" placeholder="Nama kategori baru" required><button class="btn btn-success btn-sm">+ Tambah</button></form></div></div></div></div>
